node -e "
const fs=require('fs');let s=fs.readFileSync('service.cjs','utf8');
s=s.replace('  dumps() {',\`  replay(events) {
    if(!Array.isArray(events)) throw new RangeError('events');
    const w=new Orders(this.stock,this.prices);
    w.rows=Object.fromEntries(Object.entries(this.rows).map(([k,r])=>[k,{...r}]));
    if(this.events!==undefined) w.events=Object.fromEntries(Object.entries(this.events));
    const ops={reserve:'reserve',fulfill:'fulfill',refund:'refund',expire:'expire'};
    for(const e of events) {
      if(!isObj(e)||typeof e.event!=='string'||typeof e.op!=='string'||!Array.isArray(e.args)||!Object.hasOwn(ops,e.op)) throw new RangeError('event');
      const sig=JSON.stringify([e.op,e.args]);
      if(w.events!==undefined&&Object.hasOwn(w.events,e.event)) {
        if(w.events[e.event]!==sig) throw new RangeError('conflict');
        continue;
      }
      let res;
      try {res=w[e.op](...e.args);} catch(err) {throw new RangeError('args');}
      if(e.op!=='expire'&&(res===false||res===null)) throw new RangeError('rejected');
      if(w.events===undefined) w.events={};
      Object.defineProperty(w.events,e.event,{value:sig,enumerable:true,writable:true,configurable:true});
    }
    this.stock=w.stock;this.rows=w.rows;
    if(w.events!==undefined) this.events=w.events;
  }
  dumps() {\`);
fs.writeFileSync('service.cjs',s);"
cat > test/agent-replay.test.cjs <<'EOF'
const test=require('node:test'),assert=require('node:assert/strict');
const {Orders}=require('../service.cjs');
const ev=(event,op,...args)=>({event,op,args});
test('applies events and skips exact duplicates, also across snapshot',()=>{
 const o=new Orders({x:10},{x:'7'});
 o.replay([ev('e1','reserve','a','x',4,0,10),ev('e2','fulfill','a',2,1),ev('e1','reserve','a','x',4,0,10)]);
 assert.equal(o.available('x'),6);
 const p=Orders.loads(o.dumps());
 p.replay([ev('e2','fulfill','a',2,1),ev('e3','refund','a',1),ev('e4','expire',10)]);
 assert.equal(p.available('x'),10);
 assert.equal(o.available('x'),6);
});
test('failures leave state unchanged',()=>{
 const o=new Orders({x:5});o.replay([ev('e1','reserve','a','x',2)]);
 const before=o.dumps();
 const bads=[
  [ev('n','reserve','b','x',1),ev('e1','reserve','a','x',3)],
  [ev('n','reserve','b','x',1),ev('m','bogus')],
  [ev('n','reserve','b','x',1),ev('m','reserve','c','x',0)],
  [ev('n','reserve','b','x',1),ev('m','reserve','c','x',99)],
  [ev('n','reserve','b','x',1),ev('m','fulfill','zz',1)],
  [ev('n','reserve','b','x',1),ev('m','refund','a',1)],
  [ev('n','reserve','b','x',1),{event:'k',op:'expire',args:'no'}],
  [ev('n','reserve','b','x',1),ev('n','reserve','b','x',2)],
 ];
 for(const b of bads) {assert.throws(()=>o.replay(b),RangeError);assert.equal(o.dumps(),before);}
 assert.throws(()=>o.replay('x'),RangeError);
 assert.equal(o.available('x'),3);
});
test('expiry event returns nothing and releases',()=>{
 const o=new Orders({x:2});
 assert.equal(o.replay([ev('a','reserve','h','x',2,0,5),ev('b','expire',5)]),undefined);
 assert.equal(o.available('x'),2);
});
EOF
node --test --test-reporter=tap 2>&1 | grep -E "^(not ok|# (pass|fail))"

